ALTER TABLE access_requests DROP CONSTRAINT access_requests_status_check;
ALTER TABLE access_requests ADD CONSTRAINT access_requests_status_check CHECK (status IN ('AUTHENTICATION_PENDING','BINDING_PENDING','CONSENT_PENDING','CONSENTED','AUTHORIZED','REDEEMING','EVIDENCE_COMMITTED','RELEASE_ATTEMPTED','COMPLETED','DELIVERY_UNKNOWN','REJECTED','DENIED','WITHDRAWN','EXPIRED','FAILED','CANCELLED'));
